{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Bidisomide, a piperidine-containing drug with a central quaternary-like carbon and aromatic ring, showed 42.6% absolute oral bioavailability in healthy men, directly supporting F≥20% for a related scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fexofenadine, despite being a P-gp substrate with solubility limitations, has 33% absolute oral bioavailability in humans, supporting that piperidine/tertiary alcohol-type structures can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Flavoxate, a piperidine-containing drug, showed near-complete oral bioavailability in healthy volunteers, indicating that piperidine-based drugs can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "R-Desethyloxybutynin, an antimuscarinic metabolite with a tertiary amine and hydroxylated central carbon, had 62% bioavailability in healthy adults, supporting high oral bioavailability for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Ebastine, a BCS-II antihistamine with a piperidine moiety, achieved about 40% oral bioavailability, supporting F≥20% despite solubility limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Darifenacin, an antimuscarinic with a similar therapeutic target, has 15-19% oral bioavailability due to low solubility and first-pass metabolism; this is contradictory but less transferable because of its different polar/amide features and formulation dependence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Terfenadine has <2% oral bioavailability due to extensive first-pass metabolism to fexofenadine; this is contradictory but mechanistically distinct from the query and weakly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F≥20%). The query, a biperiden-like tertiary amino alcohol with piperidine and norbornene, is supported by several moderately transferable human absolute-bioavailability measurements in piperidine/antimuscarinic/antihistamine analogues showing F=30-100%. Low-F analogues are less transferable because their poor F arises from prodrug first-pass metabolism (terfenadine), P-gp/solubility liabilities (loperamide), or different polar/amide scaffolds (darifenacin).",
  "evidence_gaps": [
    "No direct biperiden absolute bioavailability measurement is included in the evidence set.",
    "Morgan similarities are low (0.24-0.29), so quantitative extrapolation is uncertain.",
    "No data on biperiden-specific first-pass metabolism, P-gp efflux, or solubility are provided.",
    "Some supportive records are qualitative or from different formulations/species."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

